from pathlib import Path
p=Path('src/components/accounting.tsx');s=p.read_text(encoding='utf-8')
s=s.replace('export function Accounting(){', '''export function Accounting(){
 const [paymentInvoice,setPaymentInvoice]=useState<Entry|null>(null),[receiptFiles,setReceiptFiles]=useState<File[]>([]),[savingPayment,setSavingPayment]=useState(false)
 async function confirmInvoicePayment(){if(!paymentInvoice||!receiptFiles.length||savingPayment)return;setSavingPayment(true);try{const receipts:{id:string;name:string}[]=[];for(const file of receiptFiles){const id=crypto.randomUUID();await saveDocument(file,id);receipts.push({id,name:file.name})}const invoice={...paymentInvoice,paid:true,documents:[...(paymentInvoice.documents||[]),...receipts]};persist([...rows.filter(row=>row.id!=='invoice-payment-'+invoice.id).map(row=>row.id===invoice.id?invoice:row),{...invoice,id:'invoice-payment-'+invoice.id,kind:'income',date:today(),title:`Оплата счёта ${invoice.number||invoice.title}`}]);setPaymentInvoice(null);setReceiptFiles([]);toast.success('Оплата подтверждена. Сумма добавлена в доходы')}catch{toast.error('Не удалось сохранить чек. Оплата не отмечена')}finally{setSavingPayment(false)}}
''')
s=s.replace('function togglePaid(row:Entry){', "function togglePaid(row:Entry){if(row.kind==='invoice'&&!row.paid){setPaymentInvoice(row);setReceiptFiles([]);return}")
needle=' <Dialog open={!!deleting}'
dialog=''' <Dialog open={!!paymentInvoice} onOpenChange={open=>{if(!open&&!savingPayment){setPaymentInvoice(null);setReceiptFiles([])}}}><DialogContent><DialogHeader><DialogTitle>Подтверждение оплаты</DialogTitle></DialogHeader><div className="invoice-payment-details"><p>{paymentInvoice?.number} · {paymentInvoice?.title}</p><p className="text-sm text-muted-foreground">{paymentInvoice?.person}</p><strong>{money(paymentInvoice?.amount||0)}</strong></div><Field><FieldLabel htmlFor="invoice-receipt">Чек об оплате</FieldLabel><Input id="invoice-receipt" type="file" accept="image/*,.pdf" multiple disabled={savingPayment} onChange={event=>{const files=Array.from(event.target.files||[]);if(files.some(file=>!file.type.startsWith('image/')&&file.type!=='application/pdf'&&!file.name.toLowerCase().endsWith('.pdf'))){toast.error('Прикрепите фотографию или PDF чека');return}setReceiptFiles(current=>[...current,...files]);event.target.value=''}}/>{receiptFiles.map((file,index)=><div key={index} className="account-document-row"><span>{file.name}</span><Button type="button" variant="ghost" size="icon" disabled={savingPayment} aria-label={`Убрать ${file.name}`} onClick={()=>setReceiptFiles(files=>files.filter((_,i)=>i!==index))}><Trash2 size={14}/></Button></div>)}</Field><DialogFooter><Button variant="outline" disabled={savingPayment} onClick={()=>{setPaymentInvoice(null);setReceiptFiles([])}}>Отменить</Button><Button disabled={!receiptFiles.length||savingPayment} onClick={confirmInvoicePayment}>{savingPayment?'Сохранение…':'Подтвердить оплату'}</Button></DialogFooter></DialogContent></Dialog>
'''
assert needle in s;s=s.replace(needle,dialog+needle);p.write_text(s,encoding='utf-8')
p=Path('src/index.css');s=p.read_text(encoding='utf-8');s+='\n.invoice-payment-details{display:grid;gap:8px}.invoice-payment-details strong{font-size:20px}\n';p.write_text(s,encoding='utf-8')
